<?php
declare(strict_types=1);
require_once dirname(__DIR__).'/src/bootstrap.php';Auth::requireLogin();
if(!Auth::can('police_manage')){http_response_code(403);exit('Keine Berechtigung fuer Meldedaten-Exporte.');}
function csv_safe_v_police(mixed $v):string{$s=(string)($v??'');return $s!==''&&in_array($s[0],['=','+','-','@'],true)?"'".$s:$s;}
$from=(string)($_GET['from']??date('Y-m-d'));$to=(string)($_GET['to']??$from);if(!valid_date($from)||!valid_date($to)||$from>$to){http_response_code(400);exit('Ungültiger Zeitraum');}
header('Content-Type: text/csv; charset=UTF-8');header('Content-Disposition: attachment; filename="meldeliste_'.$from.'_bis_'.$to.'.csv"');echo "\xEF\xBB\xBF";$out=fopen('php://output','wb');fputcsv($out,['Buchungsreferenz','Wohnung','Anreise','Abreise','Hauptgast','Vorname','Nachname','Zweiter Nachname','Geschlecht','Dokumentart','Dokumentnummer','Supportnummer','Ausstellungsdatum','Ausstellungsland','Geburtsort','Provinz','Nationalität','Geburtsdatum','Adresse','PLZ','Ort','Land','Mobiltelefon','Festnetz','E-Mail','Beziehung','Minderjährig','Unterschrift','Meldestatus'],';');
$status=trim((string)($_GET['status']??''));$sql="SELECT b.id,b.reference,b.arrival,b.departure,b.police_status,a.code,a.name,CONCAT(g.first_name,' ',g.last_name) guest_name FROM bookings b JOIN guests g ON g.id=b.guest_id LEFT JOIN apartments a ON a.id=b.apartment_id WHERE b.status NOT IN ('cancelled','rejected') AND b.arrival BETWEEN ? AND ?";$params=[$from,$to];if(in_array($status,['open','ready','sent','error'],true)){$sql.=' AND b.police_status=?';$params[]=$status;}$sql.=' ORDER BY b.arrival,a.name';$stmt=db()->prepare($sql);$stmt->execute($params);foreach($stmt->fetchAll() as $b){$q=db()->prepare('SELECT * FROM booking_travellers WHERE booking_id=? ORDER BY is_primary DESC,id');$q->execute([(int)$b['id']]);$trav=$q->fetchAll();if(!$trav)$trav=[[]];foreach($trav as $t)fputcsv($out,array_map('csv_safe_v_police',[$b['reference'],trim(($b['code']??'').' '.($b['name']??'')),$b['arrival'],$b['departure'],$b['guest_name'],$t['first_name']??'',$t['last_name']??'',$t['second_last_name']??'',$t['gender']??'',$t['document_type']??'',$t['document_number']??'',$t['document_support_number']??'',$t['document_issue_date']??'',$t['document_country']??'',$t['place_of_birth']??'',$t['province']??'',$t['nationality']??'',$t['date_of_birth']??'',$t['address']??'',$t['postal_code']??'',$t['city']??'',$t['country']??'',$t['mobile_phone']??'',$t['fixed_phone']??'',$t['email']??'',$t['relationship_to_primary']??'',$t['minor']??'',$t['signature_status']??'',$b['police_status']]),';');}fclose($out);
